nextflow_process {

    name "Test Process SENTIEON_BWAMEM"
    tag "modules_nfcore"
    tag "modules"
    tag "sentieon"
    tag "bwamem"
    tag "bwaindex"
    tag "sentieon/bwaindex"
    tag "sentieon/bwamem"

    script "../main.nf"
    process "SENTIEON_BWAMEM"
    config "./nextflow.config"

    test("Single-End") {

        setup {
            run("SENTIEON_BWAINDEX") {
                script "../../bwaindex/main.nf"
                process {
                    """
                    input[0] = [
                        [id: 'test'],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                    ]
                    """
                }
            }
        }

        when {
            params {
                module_args = "-R \"@RG\\tID:sample_lane\\tPU:lane\\tSM:patient_sample\\tLB:sample\\tDS:fasta\\tPL:seqplatform\""
                module_out_cram = false
            }
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = SENTIEON_BWAINDEX.out.index
                input[2] = [[id: 'test'],file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]
                input[3] = [[id: 'test'],file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                        bam(process.out.bam_and_bai[0][1]).getReadsMD5(),
                        file(process.out.bam_and_bai[0][2]).name,
                        process.out.findAll { key, val -> key.startsWith("versions") }
                    ).match() }
            )
        }
    }

