                input[2] = [[id: 'test'],file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]
                input[3] = [[id: 'test'],file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)]
                """
            }
        }

        then {
            def fasta = "https://raw.githubusercontent.com/nf-core/test-datasets/refs/heads/modules/data/genomics/sarscov2/genome/genome.fasta"
            assert process.success
            assertAll(
                { assert snapshot(
                        cram(process.out.bam_and_bai[0][1], fasta).getReadsMD5(),
                        file(process.out.bam_and_bai[0][2]).name,
                        process.out.findAll { key, val -> key.startsWith("versions") }
                    ).match() }
            )
        }
    }

